/**
 * MediaService is the audio plane. The proxy bridges these streams onto
 * Telnyx Media Streaming WebSockets so an SDK can push pre-encoded audio
 * frames (its own TTS, recorded clips, anything) directly to a live caller
 * and read inbound caller audio + DTMF in the same stream.
 *
 * One bridge per call_control_id at a time. Codec is chosen per stream;
 * frames are raw audio bytes (no WAV headers, no base64).
 */
export type MediaServiceDefinition = typeof MediaServiceDefinition;
export const MediaServiceDefinition = {
  name: "MediaService",
  fullName: "photon.voice.v1.MediaService",
  methods: {
    /**
     * Unary one-shot: SDK supplies a complete pre-encoded clip; the proxy
     * attaches a media bridge, plays the clip, and tears down. Returns when
     * the clip has been queued (not when audio has finished playing).
     */
    playClip: {
      name: "PlayClip",
      requestType: PlayClipRequest as typeof PlayClipRequest,
      requestStream: false,
      responseType: PlayClipResponse as typeof PlayClipResponse,
      responseStream: false,
      options: {},
    },
    /**
     * Bidi full-duplex: SDK pushes outbound frames and receives inbound
     * caller audio + DTMF + lifecycle markers in the same stream. The first
     * client message MUST be `start`. A second concurrent stream against the
     * same call_control_id is rejected with FAILED_PRECONDITION.
     */
    mediaStream: {
      name: "MediaStream",
      requestType: MediaClientMessage as typeof MediaClientMessage,
      requestStream: true,
      responseType: MediaServerMessage as typeof MediaServerMessage,
      responseStream: true,
      options: {},
    },
  },
} as const;

export interface MediaServiceImplementation<CallContextExt = {}> {
  /**
   * Unary one-shot: SDK supplies a complete pre-encoded clip; the proxy
   * attaches a media bridge, plays the clip, and tears down. Returns when
   * the clip has been queued (not when audio has finished playing).
   */
  playClip(request: PlayClipRequest, context: CallContext & CallContextExt): Promise<DeepPartial<PlayClipResponse>>;
  /**
   * Bidi full-duplex: SDK pushes outbound frames and receives inbound
   * caller audio + DTMF + lifecycle markers in the same stream. The first
   * client message MUST be `start`. A second concurrent stream against the
   * same call_control_id is rejected with FAILED_PRECONDITION.
   */
  mediaStream(
    request: AsyncIterable<MediaClientMessage>,
    context: CallContext & CallContextExt,
  ): ServerStreamingMethodResult<DeepPartial<MediaServerMessage>>;
}

export interface MediaServiceClient<CallOptionsExt = {}> {
  /**
   * Unary one-shot: SDK supplies a complete pre-encoded clip; the proxy
   * attaches a media bridge, plays the clip, and tears down. Returns when
   * the clip has been queued (not when audio has finished playing).
   */
  playClip(request: DeepPartial<PlayClipRequest>, options?: CallOptions & CallOptionsExt): Promise<PlayClipResponse>;
  /**
   * Bidi full-duplex: SDK pushes outbound frames and receives inbound
   * caller audio + DTMF + lifecycle markers in the same stream. The first
   * client message MUST be `start`. A second concurrent stream against the
   * same call_control_id is rejected with FAILED_PRECONDITION.
   */
  mediaStream(
    request: AsyncIterable<DeepPartial<MediaClientMessage>>,
    options?: CallOptions & CallOptionsExt,
  ): AsyncIterable<MediaServerMessage>;
}

function bytesFromBase64(b64: string): Uint8Array {
  if ((globalThis as any).Buffer) {
    return Uint8Array.from((globalThis as any).Buffer.from(b64, "base64"));
  } else {
    const bin = globalThis.atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; ++i) {
      arr[i] = bin.charCodeAt(i);
    }
    return arr;
  }
}

function base64FromBytes(arr: Uint8Array): string {
  if ((globalThis as any).Buffer) {
    return (globalThis as any).Buffer.from(arr).toString("base64");
  } else {
    const bin: string[] = [];
    arr.forEach((byte) => {
      bin.push(globalThis.String.fromCharCode(byte));
    });
    return globalThis.btoa(bin.join(""));
  }
}

